hell: [
{q: "10% growth two years in a row from Rp16,800rb. Revenue in 2028?", opts: ["Rp20,328rb","Rp18,480rb","Rp20,160rb","Rp22,176rb"], answer: 0, diff: "Medium",
 explain: "16,800 × 1.10² = 16,800 × 1.21 = Rp20,328rb. Growth compounds — not 10% + 10% = 20% of the same starting number."},
{q: "Capex Rp2,500rb > CFO Rp2,450rb (FCFF −50). The right conclusion?", opts: ["Operations are losing money","Negative FCFF — investment exceeds operating cash; normal in an expansion phase","The model must be miscalculated","Dividends should be zero"], answer: 1, diff: "Medium",
 explain: "Negative FCFF = operating cash doesn't cover this year's investment. Fine when deliberate (expansion) and traceable to assets."},
{q: "DPO rises 30 → 45 days, COGS Rp9,240rb. Impact?", opts: ["Payables Rp1,155rb; WC falls Rp385rb (cash stays longer in the company)","Payables fall Rp385rb","No cash effect","Inventory rises Rp385rb"], answer: 0, diff: "Medium",
 explain: "Payables = 9,240 × 45/360 = Rp1,155rb (+385). Payables up → WC down 385 → CFO up 385. A free 'loan' from suppliers."},
{q: "Two analysts agree on revenue Rp18,480rb; A uses DSO 30, B uses DSO 45. Receivables gap?", opts: ["Rp1,540rb","Rp385rb","Rp770rb","Rp2,310rb"], answer: 2, diff: "Medium",
 explain: "A: 1,540; B: 18,480 × 45/360 = 2,310. A Rp770rb gap — from ONE differing assumption. That's why assumptions are stated."},
{q: "Capex Rp2,500rb vs dividends Rp1,500rb: which squeezes 2027 cash most?", opts: ["Capex Rp2,500rb","Dividends Rp1,500rb","Depreciation Rp550rb","ΔWC Rp175rb"], answer: 0, diff: "Easy",
 explain: "Capex 2,500 > dividends 1,500. Depreciation & ΔWC aren't the biggest cash squeezes (depreciation isn't even cash)."}
]
